{
  "sql": "SELECT i.snapshot_date AS snapshot_date, p.category AS category, AVG(i.fill_rate) AS fill_rate FROM commerce.inventory AS i JOIN commerce.products AS p ON i.product_id = p.product_id WHERE i.snapshot_date >= $1 AND i.snapshot_date < $2 GROUP BY i.snapshot_date, p.category ORDER BY 1, 2 LIMIT 200",
  "parameters": [
    "2022-12-01",
    "2022-12-31"
  ],
  "explanation": "Calculates the mean stored fill rate by product category for each snapshot date within December 2022. The query joins inventory to products to access the category dimension, filters the snapshot dates to the specified range, and groups by snapshot date and category to compute the unweighted average of non-null fill rate values."
}

